import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse(`{"title":"Page 6 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"6","title":"Page 6 | Home","prev":"/page/5/","next":"/page/7/","posts":[{"title":"如何编写Telegram Bot","url":"/posts/2022-09-24-telegram-bot/","date":"2022-09-24 11:07","tags":["bot"],"html":"<p>最近在处理如何把经纬度转换成日本的 MAPCODE 的问题。在外出行的时候，经常使用的设备都是手机，如何在手机上方便的计算旅游景点的 MAPCODE 然后使用车载导航呢？\\n我的想法是做一个 Telegram Bot，输入景点的 <a href=\\"https://maps.google.com/pluscodes/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Plus Code</a>, 然后返回 MAPCODE。</p>\\n<h2 id=\\"申请-bot\\" tabindex=\\"-1\\">申请 Bot <a class=\\"header-anchor\\" href=\\"#申请-bot\\" aria-label=\\"Permalink to &quot;申请 Bot&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先，你要去找 <a href=\\"https://t.me/botfather\\" target=\\"_blank\\" rel=\\"noreferrer\\">BotFather</a>申请 Bot。 通过简单的对话就可以创建 Bot。使用 <code>/start</code> 命令可以查看所有支持的指令。</p>\\n<p>输入， <code>/newbot</code> 就可以创建 Bot 了，通过对话模式可以设定 Bot 的名字。然后你可以得到一个属于这个 Bot 的 token，格式类似于 <code>577XXXXX:AAEMUXqXrgRE9R2jPcOXXXXX</code>。\\n拿到这个 token 就可以构建 Bot 了。</p>\\n<h2 id=\\"构建-bot-api\\" tabindex=\\"-1\\">构建 Bot API <a class=\\"header-anchor\\" href=\\"#构建-bot-api\\" aria-label=\\"Permalink to &quot;构建 Bot API&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Bot API 本质是 HTTPS API，通过构建请求来实现功能。不过构造 HTTPS 请求本身很枯燥，已经有很多现成的框架可供我们使用。本人擅长使用 JavaScript，所以选择了 <a href=\\"https://github.com/telegraf/telegraf\\" target=\\"_blank\\" rel=\\"noreferrer\\">telegraf.js</a> 这个框架。</p>\\n<h2 id=\\"bot-代码示例\\" tabindex=\\"-1\\">Bot 代码示例 <a class=\\"header-anchor\\" href=\\"#bot-代码示例\\" aria-label=\\"Permalink to &quot;Bot 代码示例&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> { Telegraf } </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> 'telegraf'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> bot</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Telegraf</span><span style=\\"color:#24292E\\">(process.env.</span><span style=\\"color:#005CC5\\">BOT_TOKEN</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">bot.</span><span style=\\"color:#6F42C1\\">start</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">ctx</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> message</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> \`I can help you to query MAPCODE with Telegram.</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">You can copy plus code from Google Maps and paste it to tell me.\`</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ctx.</span><span style=\\"color:#6F42C1\\">reply</span><span style=\\"color:#24292E\\">(message);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">bot.</span><span style=\\"color:#6F42C1\\">help</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">ctx</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ctx.</span><span style=\\"color:#6F42C1\\">replyWithMarkdownV2</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">    'Send me a [plus code](https://maps.google.com/pluscodes/)'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ctx.</span><span style=\\"color:#6F42C1\\">reply</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\`MapDoge Version \${</span><span style=\\"color:#24292E\\">process</span><span style=\\"color:#032F62\\">.</span><span style=\\"color:#24292E\\">env</span><span style=\\"color:#032F62\\">.</span><span style=\\"color:#24292E\\">npm_package_version</span><span style=\\"color:#032F62\\">}\`</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">bot.</span><span style=\\"color:#6F42C1\\">launch</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">// Enable graceful stop</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">process.</span><span style=\\"color:#6F42C1\\">once</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'SIGINT'</span><span style=\\"color:#24292E\\">, () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> bot.</span><span style=\\"color:#6F42C1\\">stop</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'SIGINT'</span><span style=\\"color:#24292E\\">));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">process.</span><span style=\\"color:#6F42C1\\">once</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'SIGTERM'</span><span style=\\"color:#24292E\\">, () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> bot.</span><span style=\\"color:#6F42C1\\">stop</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'SIGTERM'</span><span style=\\"color:#24292E\\">));</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br></div></div><p>Telegram Bot 默认都支持 <code>/start</code> 和 <code>/help</code> 命令。所以我就贴出了这两个命令的简单写法。使用成熟的框架可以大大简化编写 Bot 的复杂度。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Telegram Bot 有完善的文档和生态，编写一个 Bot 并没有想象的那么难。大家都可以尝试下，非常方便实现在手机端的一些自定义功能。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://core.telegram.org/bots/samples\\" target=\\"_blank\\" rel=\\"noreferrer\\">Bot Code Examples</a></p>\\n<p><a href=\\"https://github.com/acgotaku/mapdoge-bot\\" target=\\"_blank\\" rel=\\"noreferrer\\">mapdoge-bot</a></p>\\n"},{"title":"使用MobX管理React的状态","url":"/posts/2022-08-07-mobx-react/","date":"2022-08-07 14:43","tags":["react"],"html":"<p>使用 PWA 框架进行应用开发，不论是 Vue 还是 React，最关注的设计应该就是状态的管理了。React 生态下状态管理的框架可谓是五花八门，本人目前用过两个，分别是\\n<a href=\\"https://redux-toolkit.js.org/\\" target=\\"_blank\\" rel=\\"noreferrer\\">@reduxjs/toolkit</a> 和 <a href=\\"https://mobx.js.org/react-integration.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">mobx-react</a>。\\n个人感觉 Mobx 用起来更简洁，所以本文着重介绍 Mobx。</p>\\n<h2 id=\\"安装-mobx\\" tabindex=\\"-1\\">安装 MobX <a class=\\"header-anchor\\" href=\\"#安装-mobx\\" aria-label=\\"Permalink to &quot;安装 MobX&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>MobX 本来就可以独立 PWA 框架来使用，所以安装的时候需要安装本体和 React 集成库。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">pnpm</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> mobx-react-lite</span><span style=\\"color:#032F62\\"> mobx</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"设计-store\\" tabindex=\\"-1\\">设计 Store <a class=\\"header-anchor\\" href=\\"#设计-store\\" aria-label=\\"Permalink to &quot;设计 Store&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>为了测试 MobX 的使用，我写了一个简单的 Todo 例子，接下来讲解如何设计 Store 方便使用。</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> class</span><span style=\\"color:#6F42C1\\"> TodoList</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  @observable.shallow </span><span style=\\"color:#E36209\\">list</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> TodoItem</span><span style=\\"color:#24292E\\">[] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [];</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  constructor</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    makeObservable</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">this</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  @action</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  private</span><span style=\\"color:#6F42C1\\"> fromJS</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    this</span><span style=\\"color:#24292E\\">.list </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> this</span><span style=\\"color:#24292E\\">.list.</span><span style=\\"color:#6F42C1\\">map</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">      todo</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> TodoItem</span><span style=\\"color:#24292E\\">(todo.title, todo.id, todo.completed)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  @action</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  addTodo</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">text</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    this</span><span style=\\"color:#24292E\\">.list.</span><span style=\\"color:#6F42C1\\">push</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">new</span><span style=\\"color:#6F42C1\\"> TodoItem</span><span style=\\"color:#24292E\\">(text));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  @action</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  removeTodo</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">todo</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> TodoItem</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    this</span><span style=\\"color:#24292E\\">.list.</span><span style=\\"color:#6F42C1\\">splice</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">this</span><span style=\\"color:#24292E\\">.list.</span><span style=\\"color:#6F42C1\\">indexOf</span><span style=\\"color:#24292E\\">(todo), </span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  @action</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  removeCompleted</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    this</span><span style=\\"color:#24292E\\">.list </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> this</span><span style=\\"color:#24292E\\">.activeTodos;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  @action</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  toggleAll</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">value</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    this</span><span style=\\"color:#24292E\\">.list.</span><span style=\\"color:#6F42C1\\">forEach</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">todo</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      todo.</span><span style=\\"color:#6F42C1\\">updateCompleted</span><span style=\\"color:#24292E\\">(value);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  @computed</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  get</span><span style=\\"color:#6F42C1\\"> showTodo</span><span style=\\"color:#24292E\\">()</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> this</span><span style=\\"color:#24292E\\">.list.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#D73A49\\"> ></span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  @computed</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  get</span><span style=\\"color:#6F42C1\\"> allTodos</span><span style=\\"color:#24292E\\">()</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> TodoItem</span><span style=\\"color:#24292E\\">[] {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> this</span><span style=\\"color:#24292E\\">.list;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  @computed</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  get</span><span style=\\"color:#6F42C1\\"> completedTodos</span><span style=\\"color:#24292E\\">()</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> TodoItem</span><span style=\\"color:#24292E\\">[] {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> this</span><span style=\\"color:#24292E\\">.list.</span><span style=\\"color:#6F42C1\\">filter</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">todo</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> todo.completed);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  @computed</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  get</span><span style=\\"color:#6F42C1\\"> activeTodos</span><span style=\\"color:#24292E\\">()</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> TodoItem</span><span style=\\"color:#24292E\\">[] {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> this</span><span style=\\"color:#24292E\\">.list.</span><span style=\\"color:#6F42C1\\">filter</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">todo</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#D73A49\\"> !</span><span style=\\"color:#24292E\\">todo.completed);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br></div></div><p>不同于 React Hooks 函数式声明，Mobx 我们推荐使用 Class 方式来声明，通过修饰符来绑定属性和方法对应 MobX 的相关概念。MobX 推荐使用 action 进行数据的更改，使用 computed 完成对数据的筛选和处理。不建议直接更改声明的数据。</p>\\n<h2 id=\\"设计全局-store\\" tabindex=\\"-1\\">设计全局 Store <a class=\\"header-anchor\\" href=\\"#设计全局-store\\" aria-label=\\"Permalink to &quot;设计全局 Store&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> type</span><span style=\\"color:#6F42C1\\"> RootStore</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  todoList</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> TodoList</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#005CC5\\"> store</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> RootStore</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  todoList</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> StoreContext</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> React.</span><span style=\\"color:#6F42C1\\">createContext</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">RootStore</span><span style=\\"color:#24292E\\">>(store);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#005CC5\\"> StoreProvider</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> StoreContext.Provider;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> useStore</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> React.</span><span style=\\"color:#6F42C1\\">useContext</span><span style=\\"color:#24292E\\">(StoreContext);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br></div></div><p>通过声明全局 Store，模块化设计各个子 Store，这里虽然只有一个 todoList， 但可以根据应用规模添加子模块，方便扩展。</p>\\n<h2 id=\\"root-导入-store\\" tabindex=\\"-1\\">Root 导入 Store <a class=\\"header-anchor\\" href=\\"#root-导入-store\\" aria-label=\\"Permalink to &quot;Root 导入 Store&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">ReactDOM.</span><span style=\\"color:#6F42C1\\">createRoot</span><span style=\\"color:#24292E\\">(document.</span><span style=\\"color:#6F42C1\\">getElementById</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'root'</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#24292E\\">).</span><span style=\\"color:#6F42C1\\">render</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#005CC5\\">React.StrictMode</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;</span><span style=\\"color:#005CC5\\">StoreProvider</span><span style=\\"color:#6F42C1\\"> value</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{store}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#005CC5\\">App</span><span style=\\"color:#24292E\\"> /></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;/</span><span style=\\"color:#005CC5\\">StoreProvider</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;/</span><span style=\\"color:#005CC5\\">React.StrictMode</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>在 React 根节点声明 Store， 保证整个应用都可以同步到 store 的数据。</p>\\n<h2 id=\\"封装-view\\" tabindex=\\"-1\\">封装 View <a class=\\"header-anchor\\" href=\\"#封装-view\\" aria-label=\\"Permalink to &quot;封装 View&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们需要在使用 store 的地方，调用 observer 保证状态的更新能及时反应到视图上。</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> TodoView</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#24292E\\"> { </span><span style=\\"color:#005CC5\\">todoList</span><span style=\\"color:#24292E\\"> } </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> useStore</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;</span><span style=\\"color:#22863A\\">section</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\">\\"todoapp\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#22863A\\">header</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\">\\"header\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#22863A\\">h1</span><span style=\\"color:#24292E\\">>todos&#x3C;/</span><span style=\\"color:#22863A\\">h1</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;/</span><span style=\\"color:#22863A\\">header</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;/</span><span style=\\"color:#22863A\\">section</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> default</span><span style=\\"color:#6F42C1\\"> observer</span><span style=\\"color:#24292E\\">(TodoView);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>MobX 的状态更新原理是基于 <a href=\\"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Proxy\\" target=\\"_blank\\" rel=\\"noreferrer\\">Proxy</a>。 通过代理声明的数据对象，在读取和写入的时候执行相关回调进行更新。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/acgotaku/mobx-react-todo\\" target=\\"_blank\\" rel=\\"noreferrer\\">mobx-react-todo</a></p>\\n"},{"title":"Git 提交规范","url":"/posts/2022-07-23-git-commit-lint/","date":"2022-07-23 20:37","tags":["github"],"html":"<p>良好的代码风格很重要，但是良好的 commit 记录同样重要。我们提交代码的时候都要提交 commit message，否则就不允许提交。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> commit</span><span style=\\"color:#005CC5\\"> -m</span><span style=\\"color:#032F62\\"> \\"hello world\\"</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"commit-message-格式\\" tabindex=\\"-1\\">commit message 格式 <a class=\\"header-anchor\\" href=\\"#commit-message-格式\\" aria-label=\\"Permalink to &quot;commit message 格式&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>目前最流行的提交规范是<a href=\\"https://www.conventionalcommits.org/en/v1.0.0/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Conventional Commits</a>，格式如下：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>&#x3C;type>[optional scope]: &#x3C;description></span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>[optional body]</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>[optional footer(s)]</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><h3 id=\\"header\\" tabindex=\\"-1\\">Header <a class=\\"header-anchor\\" href=\\"#header\\" aria-label=\\"Permalink to &quot;Header&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>Header 有三个字段，type(必须)，scope(可选) 和 description(必须)。</p>\\n<p>type 用于说明 commit 的类别，有以下几个选项：build, chore, ci, docs, feat, fix, perf, refactor, revert, style, test</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>build: 对构建系统或者外部依赖项进行了修改</span></span>\\n<span class=\\"line\\"><span>chore: 构建过程或辅助工具的变动</span></span>\\n<span class=\\"line\\"><span>ci: 对CI配置文件或脚本进行了修改</span></span>\\n<span class=\\"line\\"><span>docs: 对文档进行了修改</span></span>\\n<span class=\\"line\\"><span>feat: 增加新功能</span></span>\\n<span class=\\"line\\"><span>fix: 修复BUG</span></span>\\n<span class=\\"line\\"><span>perf: 优化相关，比如提升性能，体验</span></span>\\n<span class=\\"line\\"><span>refactor: 重构代码</span></span>\\n<span class=\\"line\\"><span>revert: 回滚到上一个版本</span></span>\\n<span class=\\"line\\"><span>style: 修改代码格式</span></span>\\n<span class=\\"line\\"><span>test: 添加测试代码</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>scope 用于说明 commit 影响的范围，比如某个组件的修改。</p>\\n<p>description 是 commit 目的的简短描述，不超过 50 个字符。最好以动词开头，首字母小写，末尾不加句号(.)</p>\\n<h3 id=\\"body\\" tabindex=\\"-1\\">Body <a class=\\"header-anchor\\" href=\\"#body\\" aria-label=\\"Permalink to &quot;Body&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>Body 是可选的，用来对本次提交进行详细描述， 可以写成多行，例如：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>fix: prevent racing of requests</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>Introduce a request id and a reference to latest request. Dismiss</span></span>\\n<span class=\\"line\\"><span>incoming responses other than from latest request.</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><h3 id=\\"footer\\" tabindex=\\"-1\\">Footer <a class=\\"header-anchor\\" href=\\"#footer\\" aria-label=\\"Permalink to &quot;Footer&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>Footer 也是可选的，主要有两个使用情况。一种是不兼容性更新：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>chore!: drop support for Node 6</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>BREAKING CHANGE: use JavaScript features not available in Node 6.</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>一种是引用提交的问题，例如本次提交是修正某个 Issue 的问题。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>feat(lang): add Polish language</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>Closes #234</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>良好的 commit 提交规范和代码规范同样重要。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://www.ruanyifeng.com/blog/2016/01/commit_message_change_log.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Commit message 和 Change log 编写指南</a></p>\\n"}]},"relativePath":"page/6/index.md","filePath":"page/[page].md"}`),p={name:"page/6/index.md"};function l(e,o,r,t,c,i){return n(),a("div")}const d=s(p,[["render",l]]);export{y as __pageData,d as default};
